userscript.function:

$share.editor = { 
    frame:$(layoutObj.cells('a').cell).find('.dhx_cell_cont_layout')[0].appendChild($('<iframe class="contract-editor-frame" style="width:100%;height:100%;border:0px;padding:0px;margin:0px;"></iframe>')[0])
}

if(Sepoa.request.isPopup && $sObject._vp.parents('.sepoaux.screen_area').length <= 0){
    var config = {
        module:{
            WORK_TYPE : Sepoa.request.WORK_TYPE || 'C',
            CONT_TYPE : Sepoa.request.CONT_TYPE || 'B',
            CONT_MODULE : Sepoa.request.CONT_MODULE || 'EDITOR'
        },
        document : {
            CONT_NO : Sepoa.request.CONT_NO,
            CONT_GL_SEQ : Sepoa.request.CONT_GL_SEQ,
            CONT_TYPE : Sepoa.request.CONT_TYPE || 'B'
        },
        editor:{}
    }
    doOpenDocument(config);
}else {
    callFunction('p', 'childScreenReady', [{
        name:"MODULE",
        id: $sObject.aliasCode,
        fn:{
            doOpenDocument:doOpenDocument,
            doUpdateShare:doUpdateShare,
            doClear:doClear
        }
    }])
}


if(flag !== false){
    var config = {
        url:window.CONTEXT_NAME+'/SepoaActionController.sux',
        on:{
            callback:function(res, config, params){
                if(res.status == "1"){
                    data.document = $.extend(true, data.document, res.result[0]);
                    adjustConfiguration(data);
                    loadEditor();
                }else{
                    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0002'), function(){
                        doClose();
                    });
                }
            }
        }
    }
    var params = {
        module:"contract" + (data.module.WORK_TYPE=='T'?".template":""),
        action: "doDocumentDetail",
        CONNECTION: "CONNECTION",
        CONT_TYPE: data.module.CONT_TYPE,
        CONT_NO: data.document.CONT_NO,
        CONT_GL_SEQ: data.document.CONT_GL_SEQ
    }

    sUtils.multipart.send(config, params);
    changeHeaderText('a', sUtils.cache.text.get('POA_CONTRACT.TITLE_'+data.module.CONT_MODULE))
}else{
    $share.config = data;
    loadEditor();       
}


if(Sepoa.request.isPopup && Sepoa.request.isRealPopup){
    if(!Sepoa.request.onLink){
        window.close();
    }else{
        document.location.reload();
    }
}else if(Sepoa.request.isPopup){
    selfObj.close();
}else{
    doClear();
    callFunction('p', 'changeView', [{view:'LIST'}])
}


$share.config = config;
if("C" == config.module.WORK_TYPE){
    if("EDITOR" == config.module.CONT_MODULE){
        config.editor.header=[
            {
                type:'button',
                position:'float',
                list:[
                    {id:"SAVE"  	, text:"{BUTTON.save}"  	, type:"save"   	, onclick:function(){onButtonClick('SAVE')}},
                    {id:"SEND"  	, text:"{BUTTON.send}"  	, type:"primary"	, onclick:function(){onButtonClick('SEND')}},
                    {id:"CANCEL"	, text:"{BUTTON.cancel}"	, type:"back"   	, onclick:function(){onButtonClick('CANCEL')}},
                    {id:"DOWNLOAD"	, text:"{BUTTON.download}"	, type:"secondary"	, onclick:function(){onButtonClick('DOWNLOAD')}}
                ]
            }
        ]
    }else if("SIGN" == config.module.CONT_MODULE || "COMPLETE" == config.module.CONT_MODULE){
        var signStatusMap = {
            'M': {lang: sUtils.cache.text.get('POA_CONTRACT.LABEL_SIGN_STATUS_M'), status:'PROGRESS'},
            'W': {lang: sUtils.cache.text.get('POA_CONTRACT.LABEL_SIGN_STATUS_W'), status:'WAIT'},  
            'C': {lang: sUtils.cache.text.get('POA_CONTRACT.LABEL_SIGN_STATUS_C'), status:'REJECT'},
            'S': {lang: sUtils.cache.text.get('POA_CONTRACT.LABEL_SIGN_STATUS_S'), status:'COMPLETE'}
        }  

        var currSignInfo = null
        var signerItemList = [];
        for(var i in $share.config.document.SIGNER){
            var signer = $share.config.document.SIGNER[i];
            if(signer.SIGN_FLAG == "M" 
                && signer.SIGNER_COMPANY_CODE == Sepoa.info.COMPANY_CODE
                && signer.SIGNER_ID == Sepoa.info.ID){
                currSignInfo = signer.SIGNER_NO;
            }

            var flowItem = {
                id:signer.SIGNER_NO,
                label:signStatusMap[signer.SIGN_FLAG].lang,
                status:signStatusMap[signer.SIGN_FLAG].status,
                data:{
                    status:signer.SIGN_FLAG
                },
                list:[
                    {text: signer.SIGNER_COMPANY_NAME},
                    {text: signer.SIGNER_NAME}
                ]
            }
            if(signer.SIGN_COMMENT){
                flowItem.data.SIGN_COMMENT = signer.SIGN_COMMENT;
                flowItem.list[1].icon = 'message'
            }
            signerItemList.push(flowItem);
        }

        var headerButton = [];
        if("SIGN" == config.module.CONT_MODULE){
            if(currSignInfo){
                config.editor.signerNo = currSignInfo;
                headerButton.push({id:"SIGN", text:"{BUTTON.sign}", type:"primary"});
                headerButton.push({id:"SIGN_REJECT", text:"{POA_CONTRACT.BUTTON_SIGN_REJECT}", type:"default"});
            }
            headerButton.push({id:"DOWNLOAD"  , text:"{BUTTON.download}"  , type:"secondary", onclick:function(){onButtonClick('DOWNLOAD')}});
        }else if("COMPLETE" == config.module.CONT_MODULE){
            if(config.document.DOC_INFO_DATA.STATUS != "A"){
                if(sUtils.string.toBoolean($share.config.document.DOC_INFO_DATA.IS_WRITABLE)){
                    headerButton.push({id:"DELETE"  , text:"{BUTTON.delete}"  , type:"delete", onclick:function(){onButtonClick('DELETE')}});
                }
            }else if(Sepoa.info.USER_TYPE != 'S'){
                headerButton.push({id:"TERMINATION_FORCE"  , text:"{POA_CONTRACT.BUTTON_TERMINATION_FORCE}"  , type:"reject", onclick:function(){onButtonClick('TERMINATION_FORCE')}});
                headerButton.push({id:"TERMINATION"  , text:"{POA_CONTRACT.BUTTON_TERMINATION}"  , type:"primary", onclick:function(){onButtonClick('TERMINATION')}});
            }
            headerButton.push({id:"DOWNLOAD"  , text:"{BUTTON.download}"  , type:"secondary", onclick:function(){onButtonClick('DOWNLOAD')}});
        }

        if(!Sepoa.request.onLink){
            headerButton.push({id:"CANCEL", text:"{BUTTON.cancel}", type:"back"     , onclick:function(){onButtonClick('CANCEL')}});
        }

        config.editor.header=[
            {
                type:'button',
                position:'float',
                list:headerButton
            },
            {
                type:'flowview',
                options:[
                    {
                        view:'fix',
                        contents:"show",
                        template:{
                            iconContent:'<div class="sepoa-flow-view-item-contents-default">#CONTENT#<div class="sepoa-flow-view-item-contents-icon-#ICONTYPE#"></div></div>'
                        }
                    },
                    signerItemList
                ],
                events:{
                    onIconClick:function(id, data){
                        var title = Sepoa.cache.text.get('POA_CONTRACT.TITLE_SIGNCOMMENT'); //서명의견
                        sUtils.popup.modal({
                            url:'/UxDefault/Common/WindowForm.sux',
                            title:title,
                            header:false,
                            params:{
                                mode:'VIEW',
                                form:'POA_CONTRACT_SIGNCOMMENT',
                                data:data
                            }
                        })                            
                    }
                }
            }
        ]
        if("SIGN" == config.module.CONT_MODULE && currSignInfo){
            config.editor.header.push({type:'form', id:'POA_CONTRACT_SIGNCOMMENT'})
        }
    }else if("TERMINATION" == config.module.CONT_MODULE){
        var signStatusMap = {
            'M': {lang: sUtils.cache.text.get('POA_CONTRACT.LABEL_TERMINATION_STATUS_M'), status:'PROGRESS'},
            'S': {lang: sUtils.cache.text.get('POA_CONTRACT.LABEL_TERMINATION_STATUS_S'), status:'COMPLETE'}
        }  

        var currSignInfo = null
        var signerItemList = [];
        for(var i in $share.config.document.TERMINATOR){
            var signer = $share.config.document.TERMINATOR[i];
            if(signer.TERMINATION_STATUS == "M" 
                && signer.SIGNER_COMPANY_CODE == Sepoa.info.COMPANY_CODE
                && signer.SIGNER_ID == Sepoa.info.ID){
                currSignInfo = signer.SIGNER_NO;
            }

            var flowItem = {
                id:signer.SIGNER_NO,
                label:signStatusMap[signer.TERMINATION_STATUS].lang,
                status:signStatusMap[signer.TERMINATION_STATUS].status,
                data:{
                    status:signer.TERMINATION_STATUS
                },
                list:[
                    {text: signer.SIGNER_COMPANY_NAME},
                    {text: signer.SIGNER_NAME}
                ]
            }
            if(signer.SIGN_COMMENT){
                flowItem.data.SIGN_COMMENT = signer.SIGN_COMMENT;
                flowItem.list[1].icon = 'message'
            }
            signerItemList.push(flowItem);
        }

        var headerButton = [];
        if(currSignInfo){
            config.editor.signerNo = currSignInfo;
            headerButton.push({id:"TERMINATION_AGREE"  , text:"{POA_CONTRACT.BUTTON_TERMINATION}"  , type:"primary", onclick:function(){onButtonClick('TERMINATION_AGREE')}});
        }

        if(!Sepoa.request.onLink){
            headerButton.push({id:"CANCEL", text:"{BUTTON.cancel}", type:"back"     , onclick:function(){onButtonClick('CANCEL')}});
        }

        config.editor.header=[
            {
                type:'button',
                position:'float',
                list:headerButton
            },
            {
                type:'flowview',
                options:[
                    {
                        view:'fix',
                        contents:"show",
                        template:{
                            iconContent:'<div class="sepoa-flow-view-item-contents-default">#CONTENT#<div class="sepoa-flow-view-item-contents-icon-#ICONTYPE#"></div></div>'
                        }
                    },
                    signerItemList
                ]
            }
        ];
    }else if("VIEW" == config.module.CONT_MODULE){
        config.editor.header=[
            {
                type:'button',
                position:'float',
                list:[
                    {id:"CANCEL"    , text:"{BUTTON.cancel}"    , type:"back"       , onclick:function(){onButtonClick('CANCEL')}}
                ]
            }
        ]
    }
    config.editor.watermark=sUtils.cache.text.get("POA_CONTRACT.WATERMARK_"+config.document.DOC_INFO_DATA.STATUS);
    if(config.editor.watermark.indexOf("Has not found") == 0){
        delete config.editor.watermark    
    }
}


if(id == "SAVE" || id == "SEND"){
    if(!$share.editor.fn.doUpdateShare(id)){
        return;
    }
    doDocumentUpdate((id == "SAVE")?"MODULE":"END");
} else if(id == "CANCEL") {
    doClose();   
} else if(id == "DOWNLOAD") {
    doDownload();
} else if(id == "TERMINATION_FORCE"){
    doTerminationDocument(true);
} else if(id == "TERMINATION"){
    doTerminationDocument();
} else if(id == "TERMINATION_AGREE"){
    doTerminationAgree();
} else if(id == "DELETE"){
    doDeleteDocument();
}


 var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res, config, params){
            if(res.flag){
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0001'), function(){
                    doClose();
                });
            }else{
                Alert(res.message);
            }
        }
    },
    contentType:"json"
}

var params = {
    module:"contract",
    action: "doDocumentUpdate",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ:  $share.config.document.CONT_GL_SEQ,
    CONT_TYPE: $share.config.document.CONT_TYPE,
    NEXT_STEP: nextStep
}

switch(nextStep){
case "MODULE":
case "END":
    params.EDITOR_HTMLS=$share.config.document.EDITOR_HTMLS;
    params.DOC_INFO_DATA=$share.config.document.DOC_INFO_DATA;
    break;
}

sUtils.multipart.send(config, params);


 var config = {
    url:window.CONTEXT_NAME+'/SepoaActionControllerDRM.sux',
    on:{
        callback:function(res, config, params){
            if(res.flag){

            }else{
            	console.log(arguments);
                Alert(res.message);
            }
        }
    }
}

var params = {
    module:"contract",
    action: "doDocumentDownload",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ:  $share.config.document.CONT_GL_SEQ,
    CONT_TYPE: $share.config.document.CONT_TYPE
}

sUtils.multipart.download(config, params);


if(isForce){
    sUtils.popup.modal({
        url:window.CONTEXT_NAME + '/Contract/Module/InputTextArea.sux',
        width:400,
        height:300,
        title:sUtils.cache.text.get('POA_CONTRACT_EDITOR.TERMINATION_REASON_TITLE'),
        params:{
            requiredMessage:sUtils.cache.text.get('POA_CONTRACT_EDITOR.TERMINATION_REASON_VALIDATE_MESSAGE'),
            callback:function(message){
                doTerminationCall(true, message);
            }
        }
    })
}else{
    Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0029'), function(flag){
        if(flag){
            doTerminationCall(false);
        }
    });
}


var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback:function(res, config, params){
            if(res.flag){
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0001'), function(){
                    doClose();
                });
            }else{
                Alert(res.message);
            }
        }
    }
}

var params = {
    module: "contract",
    action: "doDocumentTermination",
    CONT_NO: $share.config.document.CONT_NO,
    CONT_GL_SEQ:  $share.config.document.CONT_GL_SEQ,
    CONT_TYPE: $share.config.document.CONT_TYPE,
    IS_FORCE:isForce,
    T_MESSAGE:tMessage||""
};
sUtils.multipart.send(config, params);


Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0028'), function(flag) {
    if (flag) {
        var config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            on: {
                callback:function(res, config, params){
                    if(res.flag){
                        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0001'), function(){
                            doClose();
                        });
                    }else{
                        Alert(res.message);
                    }
                }
            }
        }

        var params = {
            module: "contract",
            action: "doDocumentTerminationAgree",
            CONT_NO: $share.config.document.CONT_NO,
            CONT_GL_SEQ:  $share.config.document.CONT_GL_SEQ,
            CONT_TYPE: $share.config.document.CONT_TYPE
        };
        sUtils.multipart.send(config, params);
    }
});


Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0008'), function(flag) {
    if (flag) {
        var config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            on: {
                callback:function(res, config, params){
                    if(res.flag){
                        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0001'), function(){
                            doClose();
                        });
                    }else{
                        Alert(res.message);
                    }
                }
            }
        }

        var params = {
            module: "contract",
            action: "doDocumentDelete",
            CONT_NO: $share.config.document.CONT_NO,
            CONT_GL_SEQ:  $share.config.document.CONT_GL_SEQ,
        };
        sUtils.multipart.send(config, params);
    }
});
